CREATE TRIGGER suppression_capacity BEFORE INSERT ON suppression_policies WHEN (SELECT COUNT(*) FROM suppression_policies WHERE project=NEW.project)>=20 BEGIN SELECT RAISE(ABORT,'suppression_policy_full'); END;
