CREATE TRIGGER reproducer_run_capacity BEFORE INSERT ON reproducer_runs WHEN (SELECT COUNT(*) FROM reproducer_runs WHERE reproducer=NEW.reproducer)>=20 BEGIN SELECT RAISE(ABORT,'reproducer_run_budget'); END;
